package app.scriptlet.ui

import android.content.Context
import app.scriptlet.engine.WidgetNode
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject

/**
 * Bundled sample renderings of every preset (assets/feed_previews.json,
 * generated by preset-work/gen-previews.mjs with the network stubbed to
 * canned sample payloads). The feed draws these stored trees instead of
 * running scripts — browsing stays instant and offline, and each card
 * still shows what the widget actually looks like. The editor preview
 * is the only place a preset runs for real, with real data.
 */
internal object FeedPreviews {
    @Volatile
    private var cache: Map<String, WidgetNode>? = null

    suspend fun load(context: Context): Map<String, WidgetNode> {
        cache?.let { return it }
        val parsed = withContext(Dispatchers.Default) {
            try {
                val text = context.assets.open("feed_previews.json")
                    .bufferedReader().use { it.readText() }
                val root = JSONObject(text)
                val map = HashMap<String, WidgetNode>()
                val keys = root.keys()
                while (keys.hasNext()) {
                    val k = keys.next()
                    runCatching { map[k] = WidgetNode.fromJson(root.getJSONObject(k).toString()) }
                }
                map
            } catch (t: Throwable) {
                emptyMap()
            }
        }
        cache = parsed
        return parsed
    }
}
